+// API keys, roles and the audit trail. Keys live in `apiKeys`
+// ({ key, name, role }); every request that changes data leaves an entry in
+// `audit` ({ id, at, key, method, path, status }), where `key` is the key's
+// name, never the secret. Entries are never edited or deleted.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** Roles from least to most powerful. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for a secret, or null (compared in constant time). */
+export function findKey(store, secret) {
+  if (typeof secret !== "string" || secret === "") return null;
+  const wanted = digest(secret);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key === "string" && timingSafeEqual(digest(k.key), wanted) && !found) found = k;
+  }
+  return found;
+}
+
+/** Whether `role` may use a permission: "read", "cook" or "manage". */
+export function allows(role, permission) {
+  if (role === "manager") return true;
+  if (role === "cook") return permission === "read" || permission === "cook";
+  if (role === "viewer") return permission === "read";
+  return false;
+}
+
+/** Appends an audit entry; `at` is an ISO instant. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.at.localeCompare(a.at) || b.id - a.id);
+}
