diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..5210aae
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,56 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, bearer, KEYS, NOW } from "./helpers.js";
+
+test("no key or an unknown key is 401 in the error shape", async () => {
+  const { raw } = app();
+  for (const headers of [{}, { authorization: "Bearer nope" }, { authorization: KEYS.manager }]) {
+    const res = await raw({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.ok(res.body.error.message);
+  }
+});
+
+test("viewers may only read", async () => {
+  const { handle, store } = app();
+  const h = bearer(KEYS.viewer);
+  assert.equal((await handle({ path: "/items", headers: h })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: h });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("cooks may cook, waste, log temperatures and count, nothing else", async () => {
+  const { handle } = app();
+  const h = bearer(KEYS.cook);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: h })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", body: { qty: 1 }, headers: h })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 }, headers: h })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" }, headers: h })).status, 403);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 }, headers: h })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: h })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/jobs/nightly", headers: h })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: h })).status, 403);
+});
+
+test("changes are audited and only managers read the audit, newest first", async () => {
+  const { handle, store } = app();
+  await handle({ path: "/items" });
+  await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: bearer(KEYS.cook) });
+  await handle({ method: "POST", path: "/jobs/nightly", headers: bearer(KEYS.viewer) });
+  await handle({ method: "POST", path: "/jobs/nightly", headers: {} });
+  assert.equal(store.data.audit.length, 2);
+  const res = await handle({ path: "/audit" });
+  assert.equal(res.status, 200);
+  const at = new Date(NOW).toISOString();
+  assert.deepEqual(res.body.map(({ id, ...e }) => e), [
+    { at, key: "front of house", method: "POST", path: "/jobs/nightly", status: 403 },
+    { at, key: "line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+  assert.equal(JSON.stringify(res.body).includes(KEYS.cook), false);
+  assert.equal((await handle({ path: "/audit", headers: bearer(KEYS.viewer) })).status, 403);
+});
